def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue

                # Find this maximal same-color diagonal run.
                run = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue

                # Do not extend the opposite-color diagonal of a checkerboard.
                r0, c0 = run[0]
                r1, c1 = run[1]
                other1 = grid[r0][c1]
                other2 = grid[r1][c0]
                if other1 != bg and other2 != bg and other1 != other2:
                    continue

                for sr, sc, start in ((-dr, -dc, run[0]), (dr, dc, run[-1])):
                    rr, cc = start[0] + sr, start[1] + sc
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        out[rr][cc] = color
                        rr += sr
                        cc += sc

    return out
